import pandas as pd, numpy as np, os, json, math, sys, pathlib, itertools
DATASET_PATH = "chunks_csv/getisord/getisord_2022_energy.csv"
from pathlib import Path, PurePosixPath
# ADJACENCY_PATH is already provided by the execution environment
ADJACENCY_PATH_value = ADJACENCY_PATH  # just to use a local variable name

# 1. Load data
df = pd.read_csv(DATASET_PATH)
adj = pd.read_csv(ADJACENCY_PATH_value)

# 2. Build symmetric neighbor list for every borough
neighbors = {b: set() for b in df['borough']}
for _, row in adj.iterrows():
    b, n = row['borough'], row['neighbor']
    if b in neighbors:
        neighbors[b].add(n)
    else:
        neighbors[b] = {n}
    if n in neighbors:
        neighbors[n].add(b)
    else:
        neighbors[n] = {b}

# 3. Energy value dict
energy = df.set_index('borough')['Energy_value']

# 4. Compute local sums (borough + its neighbors)
local_sums = {}
for b in neighbors:
    group = {b}.union(neighbors[b])
    # keep only those with non-missing energy
    valid_vals = [energy[g] for g in group if g in energy.index and not pd.isna(energy[g])]
    if len(valid_vals)==0:
        continue
    local_sums[b]=sum(valid_vals)

# 5. Compute mean and std (population)
vals = np.array(list(local_sums.values()), dtype=float)
mean = vals.mean()
std  = vals.std(ddof=0)

# 6. Z-score for each borough
results = {}
for b, v in local_sums.items():
    if std==0:
        z=0
    else:
        z = (v - mean)/std
    results[b]=z

# 7. Identify hotspots/coldspots (|z|>1.96)
hotcold = []
for b, z in results.items():
    if abs(z) > 2.576:
        tag = "HOT" if z>0 else "COLD"
    elif abs(z) > 1.96:
        tag = "HOT" if z>0 else "COLD"
    else:
        continue
    # Exclude boroughs whose own energy is missing
    if pd.isna(energy.get(b, np.nan)):
        continue
    hotcold.append((b, tag, z))

# 8. Format final answer
if len(hotcold)==0:
    final_line = "FINAL ANSWER: none"
else:
    parts=[]
    for b,tag,z in sorted(hotcold):
        parts.append(f"{b} ({tag}, z-score = {z})")
    final_line = "FINAL ANSWER: " + ", ".join(parts)

# Print outputs for inspection (optional)
print("Mean of local sums:", mean)
print("Std of local sums :", std)
for b, tag, z in hotcold:
    print(b, tag, z)

# 9. The required last line
print(final_line)
